  2	import 'dart:io';
  3	
  4	import 'package:PiliPlus/http/api.dart';
  5	import 'package:PiliPlus/http/constants.dart';
  6	import 'package:PiliPlus/models/common/account_type.dart';
  7	import 'package:PiliPlus/utils/accounts.dart';
  8	import 'package:PiliPlus/utils/accounts/account.dart';
  9	import 'package:PiliPlus/utils/accounts/api_type.dart';
 10	import 'package:PiliPlus/utils/accounts/login_policy.dart';
 11	import 'package:PiliPlus/utils/app_sign.dart';
 12	import 'package:PiliPlus/utils/extension/string_ext.dart';
 13	import 'package:PiliPlus/utils/platform_utils.dart';
 14	import 'package:PiliPlus/utils/storage_pref.dart';
 15	import 'package:connectivity_plus/connectivity_plus.dart';
 16	import 'package:dio/dio.dart';
 17	import 'package:flutter/foundation.dart' show kDebugMode;
 18	import 'package:flutter_smart_dialog/flutter_smart_dialog.dart';
 19	import 'package:material_ui/material_ui.dart';
 20	
 21	final _setCookieReg = RegExp('(?<=)(,)(?=[^;]+?=)');
 22	
 23	class AccountManager extends Interceptor {
 24	  AccountManager();
 25	
 26	  static String blockServer = Pref.blockServer;
 27	
 28	  static String getCookies(List<Cookie> cookies) {
 29	    // Sort cookies by path (longer path first).
 30	    cookies.sort((a, b) {
 31	      if (a.path == null && b.path == null) {
 32	        return 0;
 33	      } else if (a.path == null) {
 34	        return -1;
 35	      } else if (b.path == null) {
 36	        return 1;
 37	      } else {
 38	        return b.path!.length.compareTo(a.path!.length);
 39	      }
 40	    });
 41	    return cookies.map((cookie) => '${cookie.name}=${cookie.value}').join('; ');
 42	  }
 43	
 44	  @override
 45	  void onRequest(RequestOptions options, RequestInterceptorHandler handler) {
 46	    final path = options.path;
 47	
 48	    final account = _bindRequestAccount(options);
 49	
 50	    // call sites may have put the account's access_key in the params before
 51	    // the policy anonymized the request: scrub it (and re-sign) so the
 52	    // anonymous request cannot be tied to the account
 53	    if (account is! LoginAccount) _scrubAccessKey(options);
 54	
 55	    if (account is NoAccount || _skipCookie(path)) return handler.next(options);
 56	
 57	    if (!account.isLogin && path == Api.heartBeat) {
 58	      return handler.reject(
 59	        DioException.requestCancelled(requestOptions: options, reason: null),
 60	        false,
 61	      );
 62	    }
 63	
 64	    final isApp = path.startsWith(HttpString.appBaseUrl);
 65	
 66	    if (isApp && options.responseType == ResponseType.bytes) {
 67	      options.headers.addAll(account.grpcHeaders);
 68	      return handler.next(options);
 69	    }
 70	
 71	    options.headers
 72	      ..addAll(account.headers)
 73	      ..['referer'] ??= HttpString.baseUrl;
 74	
 75	    // app端不需要管理cookie
 76	    if (isApp) {
 77	      // if (kDebugMode) debugPrint('is app: ${options.path}');
 78	      final dataPtr = (options.method == 'POST' && options.data is Map
 79	          ? (options.data as Map).cast<String, dynamic>()
 80	          : options.queryParameters);
 81	      if (dataPtr.isNotEmpty) {
 82	        if (!account.accessKey.isNullOrEmpty) {
 83	          dataPtr['access_key'] = account.accessKey!;
 84	        }
 85	        AppSign.appSign(dataPtr..remove('sign'));
 86	        // if (kDebugMode) debugPrint(dataPtr.toString());
 87	      }
 88	      return handler.next(options);
 89	    } else {
 90	      account.cookieJar
 91	          .loadForRequest(options.uri)
 92	          .then((cookies) {
 93	            final previousCookies =
 94	                options.headers[HttpHeaders.cookieHeader] as String?;
 95	            final newCookies = getCookies([
 96	              ...?previousCookies
 97	                  ?.split(';')
 98	                  .where((e) => e.isNotEmpty)
 99	                  .map(Cookie.fromSetCookieValue),
100	              ...cookies,
101	            ]);
102	            options.headers[HttpHeaders.cookieHeader] = newCookies.isNotEmpty
103	                ? newCookies
104	                : '';
105	            handler.next(options);
106	          })
107	          .catchError((Object e, StackTrace s) {
108	            final err = DioException(
109	              requestOptions: options,
110	              error: e,
111	              stackTrace: s,
112	            );
113	            handler.reject(err, true);
114	          });
115	    }
116	  }
117	
118	  @override
119	  void onResponse(Response response, ResponseInterceptorHandler handler) {
120	    if (_boundRequestAccount(response.requestOptions) case final account?) {
121	      final future = _saveCookies(
122	        account,
123	        response,
124	      ).whenComplete(() => handler.next(response));
125	      assert(() {
126	        future.catchError(
127	          (Object e, StackTrace s) {
128	            throw DioException(
129	              requestOptions: response.requestOptions,
130	              error: e,
131	              stackTrace: s,
132	            );
133	          },
134	        );
135	        return true;
136	      }());
137	    } else {
138	      return handler.next(response);
139	    }
140	  }
141	
142	  @override
143	  void onError(DioException err, ErrorInterceptorHandler handler) {
144	    final options = err.requestOptions;
145	    if (options.responseType == ResponseType.stream) {
146	      return handler.next(err);
147	    }
148	
149	    if (options.method != 'POST') toast(err);
150	
151	    if (err.response case final res?) {
152	      if (_boundRequestAccount(options) case final account?) {
153	        _saveCookies(account, res).then(
154	          (_) => handler.next(err),
155	          onError: (Object e, StackTrace s) => handler.next(
156	            DioException(
157	              requestOptions: options,
158	              error: e,
159	              stackTrace: s,
160	            ),
161	          ),
162	        );
163	        return;
164	      }
165	    }
166	    return handler.next(err);
167	  }
168	
169	  static void toast(DioException err) {
170	    const skipShow = [
171	      'heartbeat',
172	      'history/report',
173	      'roomEntryAction',
174	      'seg.so',
175	      'online/total',
176	      'github',
177	      'hdslb.com',
178	      'biliimg.com',
179	      'site/getCoin',
180	    ];
181	    String url = err.requestOptions.uri.toString();
182	    if (kDebugMode) debugPrint('🌹🌹ApiInterceptor: $url\n$err');
183	    if (skipShow.any(url.contains) ||
184	        (url.contains('skipSegments') && err.requestOptions.method == 'GET')) {
185	      // skip
186	    } else {
187	      dioError(err).then((res) => SmartDialog.showToast(res + url));
188	    }
189	  }
190	
191	  static Future<void> _saveCookies(Account account, Response response) async {
192	    final setCookies = response.headers[HttpHeaders.setCookieHeader];
193	    if (setCookies == null || setCookies.isEmpty) {
194	      return;
195	    }
196	    final List<Cookie> cookies = setCookies
197	        .map((str) => str.split(_setCookieReg))
198	        .expand((cookie) => cookie)
199	        .where((cookie) => cookie.isNotEmpty)
200	        .map(Cookie.fromSetCookieValue)
201	        .toList();
202	    final statusCode = response.statusCode ?? 0;
203	    final locations = response.headers[HttpHeaders.locationHeader] ?? const [];
204	    final isRedirectRequest = statusCode >= 300 && statusCode < 400;
205	    final originalUri = response.requestOptions.uri;
206	    final realUri = originalUri.resolveUri(response.realUri);
207	    await account.cookieJar.saveFromResponse(realUri, cookies);
208	    if (isRedirectRequest && locations.isNotEmpty) {
209	      final originalUri = response.realUri;
210	      await Future.wait(
211	        locations.map(
212	          (location) => account.cookieJar.saveFromResponse(
213	            // Resolves the location based on the current Uri.
214	            originalUri.resolve(location),
215	            cookies,
216	          ),
217	        ),
218	      );
219	    }
220	    await account.onChange();
221	  }
222	
223	  static bool _skipCookie(String path) {
224	    return path.startsWith(blockServer) ||
225	        path.contains('hdslb.com') ||
226	        path.contains('biliimg.com');
227	  }
228	
229	  static Account _findAccount(String path) => ApiType.loginApi.contains(path)
230	      ? AnonymousAccount()
231	      : Accounts.get(
232	          AccountType.values.firstWhere(
233	            (i) => ApiType.apiTypeSet[i]?.contains(path) == true,
234	            orElse: () => AccountType.main,
235	          ),
236	        );
237	
238	  /// Login-flow calls that act on an explicitly passed account (e.g. logging
239	  /// it out); they keep that account whatever the mode.
240	  static const _explicitAccountApis = {
241	    Api.logout,
242	    Api.activateBuvidApi,
243	    Api.qrcodeConfirm,
244	  };
245	
246	  static Account _bindRequestAccount(RequestOptions options) {
247	    assert(options.extra['account'] is Account?);
248	    final explicit = options.extra['account'] as Account?;
249	    if (explicit is LoginAccount &&
250	        _explicitAccountApis.contains(options.path)) {
251	      return explicit;
252	    }
253	    // LibrePili: no global login. Even in login mode the account is only
254	    // attached where it is required; everything else goes out anonymously.
255	    return options.extra['account'] = LoginPolicy.bind(
256	      explicit ?? _findAccount(options.path),
257	      options,
258	    );
259	  }
260	
261	  static const _accessKeys = ['access_key', 'mobile_access_key'];
262	
263	  static void _scrubAccessKey(RequestOptions options) {
264	    void scrub(Map<String, dynamic> params) {
265	      var removed = false;
266	      for (final key in _accessKeys) {
267	        if (params.containsKey(key)) {
268	          params.remove(key);
269	          removed = true;
270	        }
271	      }
272	      if (removed && params.containsKey('sign')) {
273	        AppSign.appSign(params..remove('sign'));
274	      }
275	    }
276	
277	    scrub(options.queryParameters);
278	    if (options.data case final Map data) {
279	      scrub(data.cast<String, dynamic>());
280	    }
281	  }
282	
283	  static Account? _boundRequestAccount(RequestOptions options) {
284	    final path = options.path;
285	    final account = options.extra['account'] as Account;
286	    if (account is NoAccount ||
287	        path.startsWith(HttpString.appBaseUrl) ||
288	        _skipCookie(path)) {
289	      return null;
290	    }
291	    return account;
292	  }
293	
294	  static Future<String> dioError(DioException error) async {
295	    switch (error.type) {
296	      case .badCertificate:
297	        return '证书有误！';
298	      case .badResponse:
299	        return '服务器异常，请稍后重试！';
300	      case .cancel:
301	        return '请求已被取消，请重新请求';
302	      case .connectionError:
303	        return '连接错误，请检查网络设置';
304	      case .connectionTimeout:
305	        return '网络连接超时，请检查网络设置';
306	      case .receiveTimeout:
307	        return '响应超时，请稍后重试！';
308	      case .sendTimeout:
309	        return '发送请求超时，请检查网络设置';
310	      case .transformTimeout:
311	        return '转换响应数据超时！';
312	      case .unknown:
313	        String desc;
314	        try {
315	          desc = PlatformUtils.isMobile
316	              ? (await Connectivity().checkConnectivity()).first.desc
317	              : '';
318	        } catch (_) {
319	          desc = '';
320	        }
321	        return '$desc网络异常 ${error.error}';
322	    }
323	  }
324	}
325	
326	extension _ConnectivityResultExt on ConnectivityResult {
327	  String get desc => const ['蓝牙', 'Wi-Fi', '局域', '流量', '无', '代理', '其他'][index];
328	}

