abstract final class LoginUtils {
  static FutureOr setWebCookie([Account? account]) {
    if (Platform.isLinux) return null;
    final cookies = (account ?? Accounts.main).cookieJar.toList();
    final webManager = web.CookieManager.instance(
      webViewEnvironment: webViewEnvironment,
    );
    return Future.wait(
      cookies.map(
        (cookie) => webManager.setCookie(
          url: web.WebUri(
            '${Platform.isWindows ? 'https://' : ''}${cookie.domain}',
          ),
          name: cookie.name,
          value: cookie.value,
          path: cookie.path ?? '/',
          domain: cookie.domain,
          isSecure: cookie.secure,
          isHttpOnly: cookie.httpOnly,
        ),
      ),
    );
  }

  /// LibrePili: pages in the in-app WebView are anonymous. Removes the stored
  /// accounts' cookies (e.g. installed by an older build) and installs the
  /// anonymous jar; account cookies go in only for explicit account flows
  /// (the "reset cookie" menu, taking notes).
  static FutureOr setAnonymousWebCookie() async {
    if (Platform.isLinux) return null;
    final webManager = web.CookieManager.instance(
      webViewEnvironment: webViewEnvironment,
    );
    await Future.wait([
      for (final account in Accounts.account.values)
        for (final cookie in account.cookieJar.toList())
          webManager.deleteCookie(
            url: web.WebUri(
              '${Platform.isWindows ? 'https://' : ''}${cookie.domain}',
            ),
            name: cookie.name,
            path: cookie.path ?? '/',
            domain: cookie.domain,
          ),
    ]);
    return setWebCookie(AnonymousAccount());
  }

  static Future<void> onLoginMain() async {
    final account = Accounts.main;
    final res = await UserHttp.userInfo();
    if (res case Success(:final response)) {
      setAnonymousWebCookie();
      RequestUtils.syncHistoryStatus();
      if (response.isLogin == true) {
        final accountService = Get.find<AccountService>()
          ..face.value = response.face!;

        if (accountService.isLogin.value) {
          accountService.isLogin.refresh();
        } else {
          accountService.isLogin.value = true;
        }

        SmartDialog.showToast('main登录成功');
        if (response != Pref.userInfoCache) {
          await GStorage.userInfo.put('userInfoCache', response);
        }
      }
    } else {
      // 获取用户信息失败
      final errMsg = res.toString();
      if (errMsg == '账号未登录') {
        await Accounts.deleteAll({account});
        SmartDialog.showNotify(
          msg: '登录失败，请检查cookie是否正确，$errMsg',
          notifyType: .warning,
        );
      } else {
        SmartDialog.showToast(errMsg);
      }
    }
  }

  static Future<void> onLogoutMain() {
    Get.find<AccountService>()
      ..face.value = ''
      ..isLogin.value = false;

    return Future.wait([
    return Future.wait([
      userInfo.close(),
      historyWord.close(),
      localCache.close(),
      setting.close(),
      video.close(),
      Accounts.account.close(),
      watchProgress.close(),
      for (final box in LocalLibrary.boxes) box.close(),
      ?reply?.close(),
    ]);
  }

  static Future<List<void>> clear() {
    return Future.wait([
      userInfo.clear(),
      historyWord.clear(),
      localCache.clear(),
      setting.clear(),
      video.clear(),
      Accounts.clear(),
      watchProgress.clear(),
      LocalLibrary.clear(),
      ?reply?.clear(),
    ]);
  }

